--== Helpers ==
local function getRoot()
	local c = LP.Character
	return c and c:FindFirstChild("HumanoidRootPart")
end

local function getHum()
	local c = LP.Character
	return c and c:FindFirstChildOfClass("Humanoid")
end

local function posOf(i)
	if not i then
		return nil
	end
	if i:IsA("BasePart") then
		return i.Position
	end
	if i:IsA("Attachment") then
		return i.WorldPosition
	end
	if i:IsA("Model") then
		local ok, pivot = pcall(function()
			return i:GetPivot()
		end)
		if ok and pivot then
			return pivot.Position
		end
	end
	return nil
end

local function promptPos(prompt)
	return prompt and posOf(prompt.Parent) or nil
end

local function basePartOf(i)
	if i:IsA("BasePart") then
		return i
	end
	if i:IsA("Attachment") then
		return i.Parent
	end
	if i:IsA("Model") then
		return i.PrimaryPart or i:FindFirstChildWhichIsA("BasePart", true)
	end
	return nil
end

local KEY_COLORS = {
	Red = Color3.fromRGB(255, 75, 75),
	Blue = Color3.fromRGB(80, 140, 255),
	Green = Color3.fromRGB(75, 220, 115),
	Yellow = Color3.fromRGB(255, 210, 60),
	Purple = Color3.fromRGB(185, 105, 255),
}

--== World scan ==
local W = { drawers = {}, flips = {}, keys = {}, locks = {}, note = nil, opah = nil, door = nil }

local function lockPrompt(lock)
	for _, d in ipairs(lock:GetDescendants()) do
		if d:IsA("ProximityPrompt") then
			return d
		end
	end
	return nil
end

local function pickupPrompt(model)
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("ProximityPrompt") and d.ActionText == "Pick up" then
			return d
		end
	end
	return nil
end

local function scan()
	local nw = { drawers = {}, flips = {}, keys = {}, locks = {}, note = nil }
	nw.opah = workspace:FindFirstChild("Opah")
	nw.door = workspace:FindFirstChild("FrontDoor")

	local chests = workspace:FindFirstChild("PuzzleChests")
	if chests then
		for _, d in ipairs(chests:GetDescendants()) do
			if d:IsA("ProximityPrompt") and d.ActionText == "Open" then
				nw.drawers[#nw.drawers + 1] = d
			end
		end
	end

	local flips = workspace:FindFirstChild("FlipFlops")
	if flips then
		for _, d in ipairs(flips:GetDescendants()) do
			if d:IsA("ProximityPrompt") and d.ActionText == "Pick up" then
				nw.flips[#nw.flips + 1] = d
			end
		end
	end

	local items = workspace:FindFirstChild("PuzzleItems")
	if items then
		for _, child in ipairs(items:GetChildren()) do
			local t = child:GetAttribute("ItemType")
			if t == "Key" then
				nw.keys[#nw.keys + 1] = child
			elseif t == "Passcode" then
				nw.note = child
				local label = child:FindFirstChild("Code", true)
				if label and label:IsA("TextLabel") and type(label.Text) == "string" and label.Text:gsub("%s", "") ~= "" then
					S.code = label.Text
				end
			end
		end
	end

	if nw.door then
		local locks = nw.door:FindFirstChild("PuzzleLocks")
		if locks then
			for _, l in ipairs(locks:GetChildren()) do
				nw.locks[#nw.locks + 1] = l
			end
		end
	end

	W = nw
end

local function opahInfo()
	local o = W.opah
	if not o or not o.Parent then
		return nil
	end
	local p = posOf(o)
	local r = getRoot()
	local d = (p and r) and (p - r.Position).Magnitude or math.huge
	return {
		model = o,
		pos = p,
		dist = d,
		chasing = o:GetAttribute("Chasing") == true,
		target = o:GetAttribute("TargetUserId"),
		state = tostring(o:GetAttribute("State")),
	}
end

--== Prompt / movement ==
local function firePrompt(prompt)
	if not prompt or not prompt.Parent or not prompt.Enabled then
		return false
	end
	pcall(function()
		prompt.RequiresLineOfSight = false
	end)
	if typeof(fireproximityprompt) == "function" then
		if pcall(fireproximityprompt, prompt) then
			return true
		end
	end
	return pcall(function()
		prompt:InputHoldBegin()
		task.wait((prompt.HoldDuration or 0) + 0.05)
		prompt:InputHoldEnd()
	end)
end

local function teleportNear(position)
	local r = getRoot()
	if not r or not position then
		return false
	end
	local from = r.Position
	local dir = Vector3.new(from.X - position.X, 0, from.Z - position.Z)
	if dir.Magnitude < 1 then
		dir = Vector3.new(0, 0, 1)
	end
	local stand = position + dir.Unit * 3 + Vector3.new(0, 2.5, 0)
	return pcall(function()
		r.CFrame = CFrame.lookAt(stand, Vector3.new(position.X, stand.Y, position.Z))
		r.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
	end)
end

local function walkTo(position, radius, timeout)
	local r, h = getRoot(), getHum()
	if not r or not h or not position then
		return false
	end
	local deadline = os.clock() + (timeout or 5)
	h:MoveTo(position)
	while os.clock() < deadline and running do
		if not r.Parent then
			return false
		end
		if (r.Position - position).Magnitude <= radius then
			return true
		end
		task.wait(0.08)
	end
	return (r.Position - position).Magnitude <= radius + 4
end

--== Hover above Opah + god mode ==
local hovering = false

connect(RunService.Heartbeat, function()
	if not running then
		return
	end
	local r = getRoot()
	local h = getHum()

	if S.god and h and h.Health > 0 then
		pcall(function()
			if h.Health < h.MaxHealth then
				h.Health = h.MaxHealth
			end
			h:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
		end)
	end

	local o = opahInfo()
	if S.above and r and o and o.pos then
		local threat = o.chasing and (o.target == LP.UserId or o.dist <= S.hoverDist)
		if threat then
			hovering = true
			pcall(function()
				r.CFrame = CFrame.new(o.pos + Vector3.new(0, S.hoverHeight, 0))
				r.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
			end)
			return
		end
	end
	hovering = false
end)

--== Auto loot / auto win ==
local blacklist = {}
local lastFinish = 0

local function submitCode()
	local digits = S.code and S.code:gsub("%s", "")
	if not digits or digits == "" then
		return false
	end
	local shared = ReplicatedStorage:FindFirstChild("PuzzleShared")
	local remotes = shared and shared:FindFirstChild("Remotes")
	local rem = remotes and remotes:FindFirstChild("SubmitPasscode")
	if rem then
		if rem:IsA("RemoteEvent") then
			pcall(function()
				rem:FireServer(digits)
			end)
			pcall(function()
				rem:FireServer(tonumber(digits))
			end)
		elseif rem:IsA("RemoteFunction") then
			pcall(function()
				rem:InvokeServer(digits)
			end)
		end
	end
	local door = W.door
	local keypad = door and door:FindFirstChild("Keypad")
	if keypad then
		for _, d in ipairs(keypad:GetDescendants()) do
			if d:IsA("ProximityPrompt") and d.Enabled then
				teleportNear(promptPos(d))
				task.wait(0.15)
				firePrompt(d)
			end
		end
	end
	return true
end

local function winFinish()
	if os.clock() - lastFinish < 8 then
		return
	end
	lastFinish = os.clock()
	setTask("win: kirim passcode")
	submitCode()
	local door = W.door
	if door then
		local p = posOf(door)
		if p then
			teleportNear(p)
		end
	end
end

local function pickTarget(origin, win)
	local best, bestRank, bestDist = nil, math.huge, math.huge
	local function add(prompt, pos, kind, rank)
		if not prompt or not prompt.Parent or not prompt.Enabled or not pos then
			return
		end
		local expire = blacklist[prompt]
		if expire and expire > os.clock() then
			return
		end
		local d = (pos - origin).Magnitude
		if not win and d > S.lootRange then
			return
		end
		if not win then
			rank = 1
		end
		if rank < bestRank or (rank == bestRank and d < bestDist) then
			best, bestRank, bestDist = { prompt = prompt, pos = pos, kind = kind }, rank, d
		end
	end

	if win or S.tNote then
		if W.note then
			local p = pickupPrompt(W.note)
			add(p, posOf(W.note), "note", 1)
		end
	end
	if win or S.tKey then
		for _, key in ipairs(W.keys) do
			add(pickupPrompt(key), posOf(key), "key", 2)
		end
	end
	if win or S.tLock then
		for _, lock in ipairs(W.locks) do
			add(lockPrompt(lock), posOf(lock), "lock", 3)
		end
	end
	if win or S.tDrawer then
		for _, p in ipairs(W.drawers) do
			add(p, promptPos(p), "drawer", 4)
		end
	end
	if win or S.tFlip then
		for _, p in ipairs(W.flips) do
			add(p, promptPos(p), "flip flop", 5)
		end
	end
	return best
end

local function lootStep()
	if not (S.autoLoot or S.autoWin) then
		return
	end
	if hovering then
		setTask("melayang di atas Opah")
		return
	end
	local r, h = getRoot(), getHum()
	if not r or not h or h.Health <= 0 or LP:GetAttribute("Out") == true then
		setTask("menunggu karakter")
		return
	end

	local win = S.autoWin
	local target = pickTarget(r.Position, win)
	if not target then
		if win then
			winFinish()
		else
			setTask("tidak ada target")
		end
		return
	end

	setTask((win and "win: " or "loot: ") .. target.kind)
	if S.walk then
		if not walkTo(target.pos, 7, 5) then
			teleportNear(target.pos)
		end
	else
		teleportNear(target.pos)
	end
	task.wait(0.12)
	firePrompt(target.prompt)
	blacklist[target.prompt] = os.clock() + (target.kind == "lock" and 12 or 6)
	task.wait(0.15)
end

task.spawn(function()
	while running do
		local ok, err = pcall(lootStep)
		if not ok then
			setTask("error: " .. tostring(err))
		end
		task.wait(0.3)
	end
end)

task.spawn(function()
	while running do
		pcall(scan)
		for prompt in pairs(blacklist) do
			if prompt.Parent == nil then
				blacklist[prompt] = nil
			end
		end
		task.wait(1)
	end
end)

--== ESP ==
local esp = {}

local function destroyEntry(e)
	pcall(function()
		if e.hl then
			e.hl:Destroy()
		end
		if e.bb then
			e.bb:Destroy()
		end
	end)
end

local function flipInstance(prompt)
	local p = prompt.Parent
	if p and p:IsA("Attachment") then
		p = p.Parent
	end
	if p and p:IsA("BasePart") then
		local m = p:FindFirstAncestorOfClass("Model")
		if m and m ~= workspace then
			local ok, size = pcall(function()
				return m:GetExtentsSize()
			end)
			if ok and size.Magnitude < 8 then
				return m
			end
		end
	end
	return p
end

local function syncEsp()
	local r = getRoot()
	local cam = workspace.CurrentCamera
	local origin = r and r.Position or (cam and cam.CFrame.Position) or Vector3.new()
	local list = {}

	local function add(inst, color, text, prio)
		if not inst or not inst.Parent then
			return
		end
		local part = basePartOf(inst)
		if not part then
			return
		end
		local d = (part.Position - origin).Magnitude
		if d > S.espDist then
			return
		end
		list[inst] = { color = color, text = text, prio = prio, part = part, dist = d }
	end

	if S.espOpah and W.opah then
		add(W.opah, Color3.fromRGB(255, 60, 60), "OPAH", 1)
	end
	if S.espPlayers then
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= LP and p.Character then
				add(p.Character, Color3.fromRGB(80, 220, 255), p.DisplayName, 2)
			end
		end
	end
	if S.espKeys then
		for _, key in ipairs(W.keys) do
			local name = key:GetAttribute("KeyColor")
			add(key, KEY_COLORS[name] or Color3.fromRGB(240, 240, 240), string.upper(tostring(name or "KEY")) .. " KEY", 3)
		end
	end
	if S.espFlips then
		for _, prompt in ipairs(W.flips) do
			local inst = flipInstance(prompt)
			add(inst, Color3.fromRGB(255, 140, 220), "FLIP FLOP", 4)
		end
	end
	if S.espNote and W.note then
		add(W.note, Color3.fromRGB(255, 255, 255), "PASSCODE", 3)
	end

	-- Roblox hanya menggambar 31 Highlight sekaligus, jadi sisanya cuma label.
	local ordered = {}
	for inst, spec in pairs(list) do
		ordered[#ordered + 1] = { inst = inst, spec = spec }
	end
	table.sort(ordered, function(a, b)
		if a.spec.prio ~= b.spec.prio then
			return a.spec.prio < b.spec.prio
		end
		return a.spec.dist < b.spec.dist
	end)

	for inst, e in pairs(esp) do
		if not list[inst] or inst.Parent == nil then
			destroyEntry(e)
			esp[inst] = nil
		end
	end

	for index, item in ipairs(ordered) do
		local inst, spec = item.inst, item.spec
		local wantHighlight = index <= 28
		local e = esp[inst]
		if not e then
			e = {}
			esp[inst] = e
			local bb = Instance.new("BillboardGui")
			bb.Name = "KZA_Label"
			bb.Size = UDim2.fromOffset(150, 30)
			bb.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
			bb.AlwaysOnTop = true
			bb.MaxDistance = 5000
			bb.LightInfluence = 0
			bb.Adornee = spec.part
			local label = Instance.new("TextLabel")
			label.BackgroundTransparency = 1
			label.Size = UDim2.fromScale(1, 1)
			label.Font = Enum.Font.GothamBold
			label.TextSize = 12
			label.TextStrokeTransparency = 0.3
			label.Parent = bb
			bb.Parent = spec.part
			e.bb, e.label = bb, label
		end
		e.label.TextColor3 = spec.color
		e.label.Text = spec.text .. "\n" .. math.floor(spec.dist) .. "m"
		if wantHighlight and not e.hl then
			local hl = Instance.new("Highlight")
			hl.Name = "KZA_Highlight"
			hl.FillTransparency = 0.75
			hl.OutlineTransparency = 0
			hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			hl.Adornee = inst:IsA("Attachment") and spec.part or inst
			hl.Parent = inst:IsA("Attachment") and spec.part or inst
			e.hl = hl
		elseif not wantHighlight and e.hl then
			e.hl:Destroy()
			e.hl = nil
		end
		if e.hl then
			e.hl.FillColor = spec.color
			e.hl.OutlineColor = spec.color
		end
	end
end

local function clearEsp()
	for inst, e in pairs(esp) do
		destroyEntry(e)
		esp[inst] = nil
	end
end

task.spawn(function()
	while running do
		pcall(syncEsp)
		task.wait(0.25)
	end
end)

--== Stamina ==
local stam = { list = {}, nextScan = 0, maxSeen = {}, summary = "belum scan" }

local function refreshStam()
	local list = {}
	local function addAttrs(inst)
		if not inst then
			return
		end
		for name, value in pairs(inst:GetAttributes()) do
			if type(value) == "number" and string.find(string.lower(name), "stam") then
				list[#list + 1] = {
					owner = inst,
					name = inst.Name .. "." .. name,
					isMax = string.find(string.lower(name), "max") ~= nil,
					get = function()
						return inst:GetAttribute(name)
					end,
					set = function(v)
						inst:SetAttribute(name, v)
					end,
				}
			end
		end
	end
	local function addValues(root)
		if not root then
			return
		end
		for _, d in ipairs(root:GetDescendants()) do
			if (d:IsA("NumberValue") or d:IsA("IntValue")) and string.find(string.lower(d.Name), "stam") then
				list[#list + 1] = {
					owner = d.Parent,
					name = d:GetFullName(),
					isMax = string.find(string.lower(d.Name), "max") ~= nil,
					get = function()
						return d.Value
					end,
					set = function(v)
						d.Value = v
					end,
				}
			end
		end
	end

	addAttrs(LP)
	addAttrs(LP.Character)
	addAttrs(getHum())
	for _, child in ipairs(LP:GetChildren()) do
		if child.Name ~= "PlayerGui" then
			addValues(child)
		end
	end
	addValues(LP.Character)

	stam.list = list
	local names = {}
	for _, e in ipairs(list) do
		names[#names + 1] = e.name
	end
	stam.summary = #list == 0 and "tidak ada stamina Value/Attribute" or (#list .. ": " .. table.concat(names, ", "))
end

local function applyStam()
	if S.stam == "Off" then
		return
	end
	if os.clock() >= stam.nextScan then
		stam.nextScan = os.clock() + 3
		pcall(refreshStam)
	end
	local maxByOwner = {}
	for _, e in ipairs(stam.list) do
		if e.isMax then
			local ok, v = pcall(e.get)
			if ok and type(v) == "number" then
				if S.stam == "Custom" then
					pcall(e.set, S.stamVal)
					v = S.stamVal
				end
				maxByOwner[e.owner] = v
			end
		end
	end
	for _, e in ipairs(stam.list) do
		if not e.isMax then
			local ok, cur = pcall(e.get)
			if ok and type(cur) == "number" then
				local key = e.name
				stam.maxSeen[key] = math.max(stam.maxSeen[key] or 0, cur)
				if S.stam == "Custom" then
					pcall(e.set, S.stamVal)
				else
					local target = maxByOwner[e.owner] or stam.maxSeen[key]
					if cur < target then
						pcall(e.set, target)
					end
				end
			end
		end
	end
end

task.spawn(function()
	while running do
		pcall(applyStam)
		task.wait(0.12)
	end
end)

