	label.TextSize = 11
	label.TextColor3 = PURPLE
	label.TextXAlignment = Enum.TextXAlignment.Left
	label.Text = "  " .. string.upper(text)
	label.LayoutOrder = order
	label.Parent = scroll
end

local function toggle(text, key)
	local row = newRow()
	rowLabel(row, text)
	local pill = Instance.new("Frame")
	pill.AnchorPoint = Vector2.new(1, 0.5)
	pill.Position = UDim2.new(1, -8, 0.5, 0)
	pill.Size = UDim2.fromOffset(34, 16)
	pill.BorderSizePixel = 0
	pill.Parent = row
	Instance.new("UICorner", pill).CornerRadius = UDim.new(1, 0)
	local dot = Instance.new("Frame")
	dot.Size = UDim2.fromOffset(12, 12)
	dot.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	dot.BorderSizePixel = 0
	dot.Parent = pill
	Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
	local button = Instance.new("TextButton")
	button.BackgroundTransparency = 1
	button.Size = UDim2.fromScale(1, 1)
	button.Text = ""
	button.Parent = row

	local function refresh()
		local on = S[key] == true
		pill.BackgroundColor3 = on and PURPLE or Color3.fromRGB(60, 50, 84)
		dot.Position = on and UDim2.fromOffset(20, 2) or UDim2.fromOffset(2, 2)
	end
	refreshers[#refreshers + 1] = refresh
	refresh()
	connect(button.MouseButton1Click, function()
		S[key] = not S[key]
		refresh()
	end)
end

local function stepper(text, key, min, max, step, suffix)
	local row = newRow()
	local label = rowLabel(row, text, 0.5)
	local function make(symbol, x)
		local b = Instance.new("TextButton")
		b.AnchorPoint = Vector2.new(1, 0.5)
		b.Position = UDim2.new(1, x, 0.5, 0)
		b.Size = UDim2.fromOffset(24, 22)
		b.BackgroundColor3 = Color3.fromRGB(60, 46, 100)
		b.BorderSizePixel = 0
		b.Font = Enum.Font.GothamBold
		b.TextSize = 14
		b.TextColor3 = TXT
		b.Text = symbol
		b.Parent = row
		Instance.new("UICorner", b).CornerRadius = UDim.new(0, 5)
		return b
	end
	local plus = make("+", -8)
	local minus = make("-", -86)
	local value = Instance.new("TextLabel")
	value.AnchorPoint = Vector2.new(1, 0.5)
	value.Position = UDim2.new(1, -34, 0.5, 0)
	value.Size = UDim2.fromOffset(48, 22)
	value.BackgroundTransparency = 1
	value.Font = Enum.Font.GothamBold
	value.TextSize = 11
	value.TextColor3 = Color3.fromRGB(215, 170, 255)
	value.Parent = row
	local function refresh()
		value.Text = tostring(S[key]) .. (suffix or "")
	end
	refreshers[#refreshers + 1] = refresh
	refresh()
	connect(plus.MouseButton1Click, function()
		S[key] = math.min(max, S[key] + step)
		refresh()
	end)
	connect(minus.MouseButton1Click, function()
		S[key] = math.max(min, S[key] - step)
		refresh()
	end)
	label.Text = text
end

local function button(text, callback)
	local row = newRow()
	local b = Instance.new("TextButton")
	b.Size = UDim2.fromScale(1, 1)
	b.BackgroundTransparency = 1
	b.Font = Enum.Font.GothamBold
	b.TextSize = 12
	b.TextColor3 = TXT
	b.Text = text
	b.Parent = row
	connect(b.MouseButton1Click, function()
		local ok, err = pcall(callback, b)
		if not ok then
			setTask("error: " .. tostring(err))
		end
	end)
	return b
end

local function cycle(textFor, key, options)
	local b
	b = button(textFor(), function()
		local index = 1
		for i, v in ipairs(options) do
			if v == S[key] then
				index = i
			end
		end
		S[key] = options[(index % #options) + 1]
		b.Text = textFor()
	end)
end

