--== Logo di kotak samping UI ==
local skinned = nil

local function frameShown(obj)
	local node = obj
	while node and node ~= game do
		if node:IsA("GuiObject") and not node.Visible then
			return false
		end
		if node:IsA("ScreenGui") and not node.Enabled then
			return false
		end
		node = node.Parent
	end
	return true
end

local function hubGuis()
	local out = {}
	local roots = { guiParent, LP:FindFirstChild("PlayerGui") }
	pcall(function()
		roots[#roots + 1] = game:GetService("CoreGui")
	end)
	local seen = {}
	for _, root in ipairs(roots) do
		if root then
			local ok, children = pcall(function()
				return root:GetChildren()
			end)
			if ok then
				for _, g in ipairs(children) do
					if g:IsA("ScreenGui") and not seen[g] and string.sub(g.Name, 1, 3) ~= "KZ_" and string.sub(g.Name, 1, 4) ~= "KZA_" then
						local ok2, descendants = pcall(function()
							return g:GetDescendants()
						end)
						if ok2 then
							for _, d in ipairs(descendants) do
								if d:IsA("TextLabel") and type(d.Text) == "string" and string.find(d.Text, "KizzDev") then
									seen[g] = true
									out[#out + 1] = g
									break
								end
							end
						end
					end
				end
			end
		end
	end
	return out
end

local function findSquare(g)
	local cam = workspace.CurrentCamera
	local view = cam and cam.ViewportSize or Vector2.new(1280, 720)
	local biggest, area = nil, 0
	local descendants = g:GetDescendants()
	for _, d in ipairs(descendants) do
		if d:IsA("Frame") then
			local s = d.AbsoluteSize
			local fullscreen = s.X >= view.X * 0.98 and s.Y >= view.Y * 0.98
			if s.X > 400 and s.Y > 300 and not fullscreen and s.X * s.Y > area then
				biggest, area = d, s.X * s.Y
			end
		end
	end
	local best, bestX = nil, math.huge
	for _, d in ipairs(descendants) do
		if d:IsA("GuiObject") and (d:IsA("Frame") or d:IsA("ImageButton") or d:IsA("TextButton") or d:IsA("ImageLabel")) then
			local s = d.AbsoluteSize
			if s.X >= 52 and s.X <= 130 and math.abs(s.X - s.Y) <= 4 and frameShown(d) then
				if not (biggest and d:IsDescendantOf(biggest)) and d.Name ~= "KZA_Logo" then
					local x = d.AbsolutePosition.X
					if x < bestX then
						best, bestX = d, x
					end
				end
			end
		end
	end
	return best
end

local function skin(obj)
	if obj:FindFirstChild("KZA_Logo") then
		return true
	end
	for _, d in ipairs(obj:GetDescendants()) do
		if d:IsA("ImageLabel") or d:IsA("ImageButton") then
			pcall(function()
				d.ImageTransparency = 1
			end)
		end
	end
	if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
		pcall(function()
			obj.ImageTransparency = 1
		end)
	end
	local img = Instance.new("ImageLabel")
	img.Name = "KZA_Logo"
	img.BackgroundTransparency = 1
	img.Size = UDim2.fromScale(1, 1)
	img.Position = UDim2.fromScale(0, 0)
	img.Image = logoAsset
	img.ScaleType = Enum.ScaleType.Crop
	img.ZIndex = obj.ZIndex + 10
	local corner = Instance.new("UICorner")
	local existing = obj:FindFirstChildOfClass("UICorner")
	corner.CornerRadius = existing and existing.CornerRadius or UDim.new(0, 14)
	corner.Parent = img
	img.Parent = obj
	return true
end

local function applyLogo()
	if not logoAsset then
		setTask("logo: perlu writefile + getcustomasset")
		return false
	end
	if skinned and skinned.Parent and skinned:FindFirstChild("KZA_Logo") then
		return true
	end
	for _, g in ipairs(hubGuis()) do
		local square = findSquare(g)
		if square then
			skin(square)
			skinned = square
			setTask("logo KizzDev terpasang")
			return true
		end
	end
	setTask("kotak logo belum ketemu (buka UI dulu)")
	return false
end
env.KZA_ApplyLogo = applyLogo

task.spawn(function()
	while running do
		pcall(applyLogo)
		task.wait(2)
	end
end)

--== Unload ==
local function unload()
	running = false
	for _, c in ipairs(conns) do
		pcall(function()
			c:Disconnect()
		end)
	end
	table.clear(conns)
	clearEsp()
	pcall(function()
		if skinned then
			local img = skinned:FindFirstChild("KZA_Logo")
			if img then
				img:Destroy()
			end
		end
	end)
	pcall(function()
		gui:Destroy()
	end)
	env.KZA_Unload = nil
	env.KZA_ApplyLogo = nil
	print("[KZA] unloaded")
end
env.KZA_Unload = unload

